SELECT equipment_id, equipment_name, category, status, qr_image_path,
created_at
FROM EQUIPMENT


		AND category = #{category}


ORDER BY equipment_id ASC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM EQUIPMENT


		AND category = #{category}

SELECT equipment_id
FROM EQUIPMENT
WHERE equipment_name = #{equipmentName}
AND status = 'AVAILABLE'
ORDER BY equipment_id ASC
LIMIT #{quantity}
